// Same rules, same order as 02's Decide route (first match wins; history above severity).
// Only difference: history comes from the request's prior_negative flag, not Airtable.
const cfg = $('Get config').first().json;
const reply = $('Read input').first().json;
const scored = $('Score reply').first().json;
const s = scored.output ?? {};
const check = $('Safety check').first().json;
const safetyRisk = check.error ? null : check.output?.safety_risk ?? null;
const hasPriorNegative = reply.prior_negative;

const floor = Number(cfg.confidence_floor);
const cutoff = Number(cfg.severity_escalate);
const failed = Boolean(scored.error)
  || typeof s.polarity !== 'number'
  || typeof s.severity !== 'number'
  || typeof s.confidence !== 'number';

// A safety danger is always 5. Score reply often gives a calmly worded danger 4, and asking it both
// questions at once disturbs polarity, so Safety check asks on its own and the rule is applied here.
// If that check fails, Score reply's severity stands and the reason says so.
const severity = safetyRisk === true && s.is_feedback !== false && typeof s.severity === 'number'
  ? Math.max(s.severity, 5) : s.severity;

// Reasons are read by managers on the dashboard, so they say what happened in plain words.
// A phone number or email address in a positive reply must not be offered for public posting.
const text = String(reply.raw_text || '').replace(/\[card number removed[^\]]*\]/g, '');
const hasContact = /\d(?:[\s-]?\d){9,}/.test(text) || /[\w.+-]+@[\w-]+\.[\w.-]+/.test(text);
// Highest severity a reply can have and still go straight to Ready to post. From 00 Config if set.
const testimonialMax = Number(cfg.testimonial_severity_max ?? 1);

let route, reason;
if (failed) {
  route = 'needs_review'; reason = 'The AI could not score this reply. Please read it.';
} else if (s.is_feedback === false) {
  route = 'needs_review'; reason = 'Reply unclear or not about the visit. Please read it.';
} else if (s.confidence < floor) {
  route = 'needs_review'; reason = `The AI was unsure (confidence ${s.confidence}, needs ${floor}). Please read it.`;
} else if (s.polarity < 0 && hasPriorNegative) {
  route = 'escalated'; reason = `Repeat complaint: earlier negative within ${cfg.history_lookback_days} days`;
} else if (severity >= cutoff) {
  // Severity alone decides, whatever the tone: praise wrapped round a safety problem still escalates.
  route = 'escalated'; reason = `Severity ${severity} at or above ${cutoff}`;
} else if (s.polarity < 0) {
  route = 'private_queue'; reason = `First negative, severity ${severity} below ${cutoff}`;
} else if (s.polarity > 0 && severity > testimonialMax) {
  // Plain praise scores severity 0. A "positive" reply naming a real problem is mixed or sarcastic.
  route = 'needs_review'; reason = `Positive, but it mentions a problem (severity ${severity}). Please read it before posting.`;
} else if (s.polarity > 0 && hasContact) {
  route = 'needs_review'; reason = 'Positive, but it contains a phone number or email address. Please read it before posting.';
} else if (s.polarity > 0) {
  route = 'ready_to_post'; reason = 'Positive';
} else {
  route = 'needs_review'; reason = 'Neither positive nor negative. Please read it.';
}

if (typeof safetyRisk !== 'boolean' && !failed) reason += ' (the safety check did not run)';

return [{ json: {
  route,
  route_reason: reason,
  failed,
  error: scored.error ? String(scored.error.message ?? scored.error) : null,
  is_feedback: s.is_feedback ?? null,
  polarity: s.polarity ?? null,
  severity: severity ?? null,
  model_severity: s.severity ?? null,
  safety_risk: safetyRisk,
  safety_error: typeof safetyRisk === 'boolean' ? null : String(check.error?.message ?? check.error ?? 'no answer'),
  what_happened: check.output?.what_happened ?? null,
  confidence: s.confidence ?? null,
  themes: Array.isArray(s.themes) ? s.themes.join(', ') : null,
  summary: s.summary ?? null,
  raw_text: reply.raw_text,
  config: { severity_escalate: cutoff, confidence_floor: floor, testimonial_severity_max: testimonialMax },
} }];
